const uuid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(c^crypto.getRandomValues(new Uint8Array(1))[0]&15>>c/4).toString(16));
const app=document.querySelector('#app');const money=n=>n.toLocaleString('en-EG')+' EGP';let cart=[];try{cart=JSON.parse(localStorage.getItem('yuri-order')||'[]');if(!Array.isArray(cart))cart=[];cart=cart.filter(c=>MENU.some(m=>m.id===c.id)&&Number.isInteger(c.qty)&&c.qty>0&&c.qty<=99)}catch{}let category=new URLSearchParams(location.search).get('category')||'All sushi';let query='';let requestId=uuid();const cats=['Special Offers','Combos',...new Set(MENU.map(m=>m.cat).filter(c=>!['Special Offers','Combos'].includes(c)))];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const image=(name,alt,cls='')=>'<img class="'+cls+'" src="'+(window.YURI_ASSETS[name]||'')+'" alt="'+esc(alt)+'" loading="'+(name==='hero-nigiri-v3'?'eager':'lazy')+'" decoding="async">';
function originalGallery(){return '<section class="section" id="gallery"><div class="section-head"><div><span class="eyebrow">THE ORIGINALS · منيو يوري</span><h2>Straight from <em>our menu.</em></h2></div><p class="muted">All seven original menu pages. Tap to explore.</p></div><div class="original-grid">'+['Special Ura','Nigiri & Sashimi','Hosomaki & Temaki','Bermuda, Dynamite & Mono','Salads & Noodles','Sauces','Fried Rolls'].map((n,i)=>'<button data-photo="menu'+i+'">'+image('menu'+i,n)+'<span>'+n+' </span></button>').join('')+'</div></section>'}

try{document.body.classList.toggle('large-text',localStorage.getItem('yuri-large-text')==='true')}catch{}
let styleFilter='All',collection='all',sortBy='recommended';const selectedSizes={};
const catArabic={'All sushi':'كل السوشي','Special Ura':'رولز سبيشيال','Fried Rolls':'رولز مقلي','Nigiri':'نيجيري','Hosomaki':'هوسوماكي','Uramaki':'أوراماكي','Oshi':'أوشي','Sashimi':'ساشيمي','Dynamite Rolls':'ديناميت','Combos':'الكومبو','Special Offers':'العروض','Salads & Noodles':'سلطات ونودلز','Sauces':'الصوصات'};
function displayItems(){const seen=new Set();return MENU.filter(m=>{const key=m.cat+'|'+m.name+'|'+!!m.demo;if(seen.has(key))return false;seen.add(key);return true})}
function card(m){const variants=MENU.filter(x=>x.cat===m.cat&&x.name===m.name&&!!x.demo===!!m.demo);const chosen=MENU.find(x=>x.id===(selectedSizes[m.id]||m.id))||m;const hasPhoto=!!m.asset;return '<article class="dish-card '+(!hasPhoto?'dish-text':'')+'" data-card="'+m.id+'">'+(hasPhoto?'<button class="dish-photo" data-detail="'+m.id+'" aria-label="View '+esc(m.name)+' ingredients">'+image(m.asset,m.name+' — '+(m.ingredients||m.cat))+'</button>':'<div class="dish-category">'+esc(m.cat)+'</div>')+'<div class="dish-body"><div class="dish-topline"><span>'+esc(m.cat)+'</span>'+(m.spicy?'<span class="spicy">Spicy</span>':'')+'</div><button class="dish-title" data-detail="'+m.id+'">'+esc(m.name)+'</button><p class="ingredients">'+esc(m.ingredients|| (m.cat==='Special Offers'?'Crab + shrimp + salmon mix. Choose your included noodles and sauces.':m.cat==='Combos'?'The bigger the combo, the bigger the mix.':'From the original Yuri menu.'))+'</p>'+(m.style?'<span class="style-label '+m.style.toLowerCase()+'">'+esc(m.style)+'</span>':'')+'<div class="dish-bottom"><div>'+(variants.length>1?'<div class="size-options" aria-label="Portion size">'+variants.map(x=>'<button data-size="'+x.id+'" data-base="'+m.id+'" class="'+(x.id===chosen.id?'selected':'')+'" aria-pressed="'+(x.id===chosen.id)+'">'+x.pcs+' pcs</button>').join('')+'</div>':'<span class="portion">'+(m.pcs?m.pcs+(m.pcs===1?' piece':' pieces'):'Per serving')+'</span>')+'<strong class="dish-price">'+chosen.price.toLocaleString()+' <small>EGP</small>'+(m.demo?'<sup>*</sup>':'')+'</strong></div><button class="add" data-add="'+chosen.id+'" aria-label="Add '+esc(m.name)+' '+(chosen.pcs||'')+' pieces to order">+</button></div></div></article>'}
function homePromotions(){const combos=[['16 Fried','16 pieces','Fried selection'],['30 Piece Combo','30 pieces','A little more to share'],['50 Piece Combo','50 pieces','For a bigger gathering'],['100 Piece Combo','100 pieces','The full Yuri spread']].map(([name,title,subtitle])=>({item:MENU.find(m=>m.cat==='Combos'&&m.name===name),title,subtitle}));const offers=MENU.filter(m=>m.cat==='Special Offers');return '<section class="section home-promotions" id="home-combos"><div class="section-head"><div><p class="section-kicker">COMBOS & OFFERS · الكومبو والعروض</p><h2>For the table.</h2></div><a class="textlink" href="'+siteBase+'/menu?category=Combos">See all combos</a></div><div class="home-combo-grid">'+combos.map(({item,title,subtitle})=>'<a class="home-combo" href="'+siteBase+'/menu?category=Combos"><h3>'+title+'</h3><p>'+subtitle+'</p><strong>'+item.price.toLocaleString()+' <small>EGP</small></strong></a>').join('')+'</div><div class="home-offer-heading"><h3>Sushi & noodles.</h3><p>Crab, shrimp and salmon — with noodles and sauces included.</p><a class="textlink" href="'+siteBase+'/menu?category=Special%20Offers">View offers</a></div><div class="home-offer-grid">'+offers.map((m,i)=>'<a class="home-offer" href="'+siteBase+'/menu?category=Special%20Offers"><div><h4>'+['Yuri offer','Feast','Mega'][i]+'</h4><p><strong>'+m.pcs+' sushi pieces</strong><br>'+[1,2,3][i]+' '+(i===0?'noodle dish':'noodle dishes')+' · '+(i===0?2:3)+' sauces</p></div><strong class="home-offer-price">'+m.price.toLocaleString()+' <small>EGP</small></strong></a>').join('')+'</div></section>'}

function home(){document.body.dataset.page='home';const favouriteNames=[['Philadelphia','Special Ura'],['California','Special Ura'],['Crunchy Salmon','Fried Rolls'],['Volcano','Fried Rolls']];const favourites=favouriteNames.map(([n,c])=>MENU.find(m=>m.name===n&&m.cat===c&&!m.demo));app.innerHTML='<section class="restaurant-hero"><div class="hero-text"><p class="restaurant-location">HELIOPOLIS · CAIRO</p><h1>YURI<br>SUSHI</h1><p class="hero-subtitle">Sushi & Japanese favourites.</p><p class="hero-arabic" lang="ar">يوري سوشي — مصر الجديدة</p><div class="hero-actions"><a class="primary" href="'+siteBase+'/menu">View menu <span lang="ar">المنيو</span></a><a class="hero-visit" href="'+siteBase+'/location">Location & reservations</a></div></div><figure class="hero-photograph">'+image('hero-nigiri-v3','Salmon nigiri on a dark ceramic plate — concept photograph')+'</figure></section><section class="restaurant-intro"><p>Sushi, sharing plates and an evening in Heliopolis.</p><p lang="ar">اختار السوشي اللي بتحبه، وسيب الباقي علينا.</p></section>'+homePromotions()+'<section class="section restaurant-menu-preview"><div class="section-head"><div><p class="section-kicker">THE MENU</p><h2>A few favourites.</h2></div><a class="textlink" href="'+siteBase+'/menu">See the full menu</a></div><div class="dish-grid featured-grid">'+favourites.map(card).join('')+'</div><p class="reference-footnote">Owner preview. Original Yuri prices; proposed recipes and reference photographs.</p></section><section class="restaurant-visit"><div><p class="section-kicker">COME FIND US</p><h2>Heliopolis,<br>Cairo.</h2></div><div class="visit-address"><p>3 El-Leith Ibn Saad — Midan<br>El Hegaz St, Misr El-Gedida</p><a class="textlink" href="https://maps.app.goo.gl/qRGpzgqvSsbduEg57?g_st=ic" target="_blank" rel="noopener">Open in Google Maps</a></div><div class="visit-contact"><p>Orders & reservations</p><a href="tel:+201039015405">010 39015405</a><a class="secondary" href="'+siteBase+'/location">Plan your visit</a></div></section>'}
function menuPage(){document.body.dataset.page='menu';const isOrder=sitePath==='/order';app.innerHTML='<section class="menu-heading"><div><p class="section-kicker">YURI SUSHI · يوري سوشي</p><h1>'+(isOrder?'Order online.':'Our menu.')+'</h1></div><div><p>Rolls, nigiri, sashimi & Japanese favourites.</p><a class="textlink" href="#originals">View the original menu</a></div></section><div class="menu-toolbar"><div class="search-box"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="search" type="search" aria-label="Search the menu" placeholder="Search dishes or ingredients · ابحث في المنيو"></div><select id="sort" aria-label="Sort dishes"><option value="recommended">Recommended</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select><button class="readable-button" data-readable="true" aria-pressed="'+document.body.classList.contains('large-text')+'">Larger text <span>خط كبير</span></button></div><div class="catalogue-layout"><aside class="menu-sidebar"><p class="section-kicker">CATEGORIES</p>'+['All sushi',...cats].map(c=>'<button data-cat="'+esc(c)+'" class="'+(c===category?'active':'')+'"><span>'+esc(c)+'</span><small>'+esc(catArabic[c]||'')+'</small></button>').join('')+'</aside><div class="catalogue-main"><div class="mobile-categories" aria-label="Menu categories">'+['All sushi',...cats].map(c=>'<button data-cat="'+esc(c)+'" class="'+(c===category?'active':'')+'">'+esc(c)+'</button>').join('')+'</div><div class="filter-row" aria-label="Preparation filters">'+['All','Raw','Fried','Cooked','Vegetarian'].map(c=>'<button data-style="'+c+'" aria-pressed="'+(styleFilter===c)+'" class="'+(styleFilter===c?'active':'')+'">'+c+'</button>').join('')+'<details class="collection-options"><summary>Menu options</summary><div><button data-collection="original">Yuri originals</button><button data-collection="concept">54 concept additions</button></div></details></div><section id="menulist" aria-live="polite"></section></div><aside class="order-summary" aria-label="Your order summary"><h2>Your order</h2><p class="order-summary-ar">طلبك</p><div id="sidebagitems"></div><div class="sidebag-total"><span>Subtotal</span><strong class="basket-total">0 EGP</strong></div><button class="primary" data-review-order="true">Review order</button><p class="summary-note">Prototype preview. Orders are saved for review and are not sent to the kitchen.</p></aside></div><section class="original-menu-section" id="originals"><details><summary>Yuri’s original printed menu <span>المنيو الأصلي</span></summary>'+originalGallery()+'</details></section>'+(isOrder?'<div class="order-page-note">Choose your dishes, then review your order and enter your delivery details.</div>':'');renderMenu();syncSidebar()}
function renderMenu(){const arabicTerms={'سالمون':'salmon','سلمون':'salmon','جمبري':'shrimp','جمبرى':'shrimp','تونة':'tuna','تونه':'tuna','كابوريا':'crab','كاليفورنيا':'california','فيلادلفيا':'philadelphia','فولكانو':'volcano','مقلي':'fried','أفوكادو':'avocado','خيار':'cucumber'};const needle=arabicTerms[query.trim()]||query;let items=displayItems().filter(m=>category==='All sushi'?(m.asset||m.demo):m.cat===category);if(query)items=displayItems().filter(m=>(m.name+' '+m.cat+' '+(m.ingredients||'')).toLowerCase().includes(needle.toLowerCase()));items=items.filter(m=>(styleFilter==='All'||m.style===styleFilter)&&(collection==='all'||(collection==='concept'?m.demo:!m.demo)));if(sortBy!=='recommended')items.sort((a,b)=>sortBy==='low'?a.price-b.price:b.price-a.price);document.querySelector('#menulist').innerHTML='<div class="menu-section-heading"><h2>'+esc(query?'Search results':category)+'</h2><span>'+items.length+' dishes</span></div>'+(category==='Special Offers'&&!query?'<p class="category-desc">Crab, shrimp and salmon. Choose your included noodles and sauces.</p>':'')+'<div class="dish-grid">'+items.map(card).join('')+'</div>'+(items.length?'':'<div class="empty">No dishes match these filters.<button class="secondary" data-reset="true">Show all dishes</button></div>')+'<p class="reference-footnote">* Proposed menu additions have illustrative prices and recipes. Reference photos are for owner review. <a href="'+siteBase+'/credits">Photography credits</a></p>';document.querySelectorAll('[data-cat]').forEach(b=>b.classList.toggle('active',b.dataset.cat===category));document.querySelectorAll('[data-style]').forEach(b=>{b.classList.toggle('active',b.dataset.style===styleFilter);b.setAttribute('aria-pressed',b.dataset.style===styleFilter)});document.querySelectorAll('[data-collection]').forEach(b=>b.classList.toggle('active',b.dataset.collection===collection))}
function syncSidebar(){const el=document.querySelector('#sidebagitems');if(!el)return;el.innerHTML=cart.length?cart.map((c,i)=>{const m=MENU.find(m=>m.id===c.id);return '<div class="sidebag-row"><div><strong>'+esc(m.name)+'</strong><small>'+(m.pcs?m.pcs+' pcs · ':'')+money(m.price)+'</small></div><div class="sidebag-quantity"><button data-change="'+i+'" data-delta="-1" aria-label="Remove one '+esc(m.name)+'">−</button><span>'+c.qty+'</span><button data-change="'+i+'" data-delta="1" aria-label="Add one '+esc(m.name)+'">+</button></div></div>'}).join(''):'<div class="empty-basket"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M12 16h24l3 25H9zM18 17v-6a6 6 0 0 1 12 0v6"/></svg><p>Your order is empty.</p><span>Add something you love from the menu.</span></div>';document.querySelectorAll('.basket-total').forEach(e=>e.textContent=money(totals()));document.querySelector('[data-review-order]').disabled=!cart.length}

function detail(id){id=selectedSizes[id]||id;const m=MENU.find(m=>m.id===id);const d=document.createElement('dialog');d.className='dish-detail';d.innerHTML='<button class="close" aria-label="Close dish details">×</button>'+(m.asset?image(m.asset,m.name):'')+'<div class="detail-content"><span class="eyebrow">'+esc(m.cat)+' · '+(m.pcs?m.pcs+' PIECES':'PER SERVING')+'</span><h2>'+esc(m.name)+'</h2><p>'+esc(m.ingredients||'From Yuri’s original menu. Recipe details to be confirmed by the restaurant.')+'</p>'+(m.referencePhoto?'<p class="concept-note">Proposed recipe · Reference photo · Owner preview</p>':'')+'<div class="detail-order"><strong>'+money(m.price)+(m.demo?'*':'')+'</strong><button class="primary" data-detail-add="'+id+'">Add to order +</button></div>'+(m.sourceUrl?'<a class="reference-source" href="'+esc(m.sourceUrl)+'" target="_blank" rel="noopener">Photo reference: Sumi Sushi Egypt </a>':'')+'</div>';document.body.append(d);d.querySelector('.close').onclick=()=>{d.close();d.remove()};d.querySelector('[data-detail-add]').onclick=()=>{if(m.cat==='Special Offers'){d.close();d.remove();chooseOffer(id)}else{add(id);d.close();d.remove()}};d.addEventListener('close',()=>d.remove(),{once:true});d.showModal()}

function locationPage(){document.body.dataset.page='location';app.innerHTML='<section class="page-head"><p class="section-kicker">YURI SUSHI · مصر الجديدة</p><h1>Visit Yuri.</h1></section><section class="location-layout"><figure class="location-photo">'+image('nigiri','Nigiri from Yuri Sushi’s original menu')+'</figure><div class="location-detail"><p class="section-kicker">HELIOPOLIS, CAIRO</p><h2>Make an evening of it.</h2><p class="address">3 El-Leith Ibn Saad — Midan<br>El Hegaz St, Misr El-Gedida<br>Cairo, Egypt</p><p lang="ar" dir="rtl">٣ الليث بن سعد، ميدان الحجاز، مصر الجديدة، القاهرة</p><p>Plus code: 4963+XM El Nozha</p><div class="button-row"><a class="primary" href="https://maps.app.goo.gl/qRGpzgqvSsbduEg57?g_st=ic" target="_blank" rel="noopener">Get directions <span>الاتجاهات</span></a><a class="secondary" href="tel:+201039015405">Call the restaurant</a></div><div class="booking" id="reserve"><p class="section-kicker">RESERVATIONS · احجز</p><h3>A table at Yuri.</h3><p>Call us to arrange your visit and confirm availability.<br>للحجز ومعرفة المواعيد المتاحة، كلمنا.</p><a class="textlink" href="tel:+201039015405">010 39015405</a></div></div></section>'}
function totals(){return cart.reduce((t,c)=>t+MENU.find(m=>m.id===c.id).price*c.qty,0)}
function sync(){syncSidebar();localStorage.setItem('yuri-order',JSON.stringify(cart));document.querySelector('#cartbar').hidden=!cart.length;document.querySelector('#carttotal').textContent=money(totals());document.querySelector('#cartcount').textContent='('+cart.reduce((a,c)=>a+c.qty,0)+')'}
function bag(){document.querySelector('#bagitems').innerHTML=cart.map((c,i)=>{const m=MENU.find(m=>m.id===c.id);return '<div class="bagrow"><div><p>'+esc(m.name)+'</p><small>'+esc(m.cat)+' · '+(m.pcs?m.pcs+' pcs · ':'')+money(m.price)+'</small>'+ (c.options?'<p class="muted">'+esc(c.options)+'</p>':'')+'</div><div class="qty"><button data-change="'+i+'" data-delta="-1" aria-label="Remove one '+esc(m.name)+'">−</button><span>'+c.qty+'</span><button data-change="'+i+'" data-delta="1" aria-label="Add one '+esc(m.name)+'">+</button></div></div>'}).join('')||'<p class="empty">Your order is empty · السلة فاضية</p>';document.querySelector('#summary').textContent='Subtotal · '+money(totals());document.querySelector('#checkout').hidden=!cart.length;sync()}
function add(id,options=''){requestId=uuid();const old=cart.find(c=>c.id===id&&c.options===options);if(old)old.qty=Math.min(99,old.qty+1);else cart.push({id,qty:1,options});sync();const btn=document.querySelector('[data-add="'+id+'"]');if(btn){btn.textContent='✓';setTimeout(()=>btn.textContent='+',900)}}
function chooseOffer(id){const m=MENU.find(m=>m.id===id);const n=id===MENU.find(x=>x.cat==='Special Offers').id?1:m.name.startsWith('Feast')?2:3;const s=n===1?2:3;const d=document.createElement('dialog');d.innerHTML='<button class="close" aria-label="Close offer">×</button><span class="eyebrow">YOUR INCLUDED EXTRAS</span><h2>'+esc(m.name)+'</h2><form>'+Array.from({length:n},(_,i)=>'<label>Noodles '+(i+1)+'<select name="noodle'+i+'"><option>Shrimp Noodles</option><option>Chicken Noodles</option></select></label>').join('')+Array.from({length:s},(_,i)=>'<label>Sauce '+(i+1)+'<select name="sauce'+i+'">'+MENU.filter(m=>m.cat==='Sauces').map(m=>'<option>'+esc(m.name)+'</option>').join('')+'</select></label>').join('')+'<button class="primary">Add to order · '+money(m.price)+'</button></form>';document.body.append(d);d.querySelector('.close').onclick=()=>{d.close();d.remove()};d.querySelector('form').onsubmit=e=>{e.preventDefault();const opts=[...new FormData(e.target).values()].join(', ');add(id,opts);d.close();d.remove()};d.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.reviewOrder)document.querySelector('#openbag').click();if(b.dataset.readable){document.body.classList.toggle('large-text');const enabled=document.body.classList.contains('large-text');b.setAttribute('aria-pressed',enabled);localStorage.setItem('yuri-large-text',String(enabled))}if(b.dataset.cat){category=b.dataset.cat;query='';document.querySelector('#search').value='';renderMenu();history.replaceState({},'',location.pathname+'?category='+encodeURIComponent(category))}if(b.dataset.style){styleFilter=b.dataset.style;renderMenu()}if(b.dataset.collection){collection=collection===b.dataset.collection?'all':b.dataset.collection;renderMenu()}if(b.dataset.reset){category='All sushi';styleFilter='All';collection='all';query='';document.querySelector('#search').value='';renderMenu()}if(b.dataset.size){selectedSizes[Number(b.dataset.base)]=Number(b.dataset.size);if(document.querySelector('#menulist'))renderMenu();else home()}if(b.dataset.detail){detail(Number(b.dataset.detail))}if(b.dataset.add){const id=Number(b.dataset.add);MENU.find(m=>m.id===id).cat==='Special Offers'?chooseOffer(id):add(id)}if(b.dataset.photo){document.querySelector('#fullphoto').src=(window.YURI_ASSETS[b.dataset.photo]||'');document.querySelector('#photo').showModal()}if(b.classList.contains('close'))b.closest('dialog').close();if(b.dataset.change!==undefined){const c=cart[Number(b.dataset.change)];c.qty+=Number(b.dataset.delta);c.qty=Math.min(99,c.qty);cart=cart.filter(c=>c.qty>0);bag()}});
document.querySelector('#openbag').onclick=()=>{bag();document.querySelector('#orderstatus').textContent='';document.querySelector('#submitorder').hidden=false;document.querySelector('#bag').showModal()};document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;renderMenu()}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sortBy=e.target.value;renderMenu()}});
document.querySelector('#checkout').onsubmit=async e=>{e.preventDefault();const form=e.target;const status=document.querySelector('#orderstatus');const btn=document.querySelector('#submitorder');btn.disabled=true;status.textContent='Sending your order…';try{const r=await fetch('/api/order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...Object.fromEntries(new FormData(form)),items:cart,request_id:requestId,prototype:true})});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not send order. Please call 010 39015405.');status.textContent='Demo order saved · تم حفظ الطلب التجريبي. This is an owner preview, not a kitchen order. Reference: '+data.reference;requestId=uuid();cart=[];sync();form.reset();btn.hidden=true}catch(err){status.textContent=err.message}finally{btn.disabled=false}};
if(sitePath==='/menu'||sitePath==='/order')menuPage();else if(sitePath==='/location')locationPage();else home();document.querySelectorAll('nav a').forEach(a=>{if(a.getAttribute('href')===sitePath)a.setAttribute('aria-current','page')});sync();
